    await expect(page.getByRole("button", { name: "Alphabetical", exact: true })).toHaveText("Alphabetical");
    await page.getByRole("textbox", { name: "Search..." }).fill("pasta");
    await expect(page.getByRole("textbox", { name: "Search..." })).toHaveValue("pasta");
